mapper.sql:
where 1=1

		and cmov_llave = #{llaveTabla}


		and cmov_estado = #{estado}


		and cmov_tipo = #{tipo}


		and dmov_fecharegistro >= #{fechaRegistroMin}


		and dmov_fecharegistro  <   #{fechaRegistroMax}


		and dmov_fechaevento >= #{fechaEventoMin}


		and dmov_fechaevento  <   #{fechaEventoMax}


		and cmov_cuenta = #{cuenta}


		and cmov_turno = #{turno}


		and cmov_anterior = #{anterior}


		and cmov_siguiente = #{siguiente}


		and cmov_relacionado = #{relacionado}


		and cmov_documento = #{documento}


		and (upper(cmov_nombre) like upper('%' || #{filtroParametro} || '%'))
